<template>
 <main class="sl-service intl-screen">
  <section class="sl-card"><p v-if="busy" role="status">Please wait…</p>
   <fieldset :disabled="busy || !!attempt"><label class="sl-field" for="intl-country">Country</label>
   <button id="intl-country" type="button" class="sl-input intl-country-trigger" :aria-expanded="countryPickerOpen" aria-controls="intl-country-options" @click="openCountryPicker"><span>{{ selectedCountry?flag(selectedCountry.code)+' '+selectedCountry.name:'Select country' }}</span><span aria-hidden="true">⌄</span></button>
   <div v-if="countryPickerOpen" id="intl-country-options" class="intl-country-picker" @keydown.esc="countryPickerOpen=false"><input ref="countrySearchInput" v-model="countrySearch" class="sl-input" type="search" placeholder="Search countries" aria-label="Search countries"><ul role="listbox" aria-label="Countries"><li v-for="c in filteredCountries" :key="c.code"><button type="button" role="option" :aria-selected="country===c.code" @click="selectCountry(c)">{{ flag(c.code) }} {{ c.name }} <small>{{ c.calling_code }}</small></button></li></ul><p v-if="!filteredCountries.length" class="sl-muted">No countries found.</p></div>
   <label class="sl-field">Type</label><div class="sl-row"><button v-for="t in ['airtime','data']" :key="t" type="button" class="sl-btn sl-grow" :class="type===t?'':'ghost'" :aria-pressed="type===t" @click="type=t;loadOperators()">{{ t==='airtime'?'Airtime':'Data' }}</button></div>
   <label class="sl-field" for="intl-phone">Phone Number</label><div class="intl-phone"><strong>{{ selectedCountry?.calling_code }}</strong><input id="intl-phone" v-model.trim="phone" type="tel" class="sl-input" placeholder="Enter phone number" maxlength="20" @input="phoneChanged" @blur="loadPrices"></div>
   <label class="sl-field">Choose operator</label><div class="sl-platforms"><button v-for="o in operators" :key="o.id" type="button" class="sl-platform" :class="{active:operator?.id===o.id}" :aria-pressed="operator?.id===o.id" @click="choose(o)"><img v-if="o.logo?.startsWith('https://') || o.logo?.startsWith('/template/images/services/')" :src="o.logo" alt="" @error="logoFailed($event,o)"><span>{{ o.name }}</span></button></div><p v-if="country && !operators.length && !busy && !message" class="sl-muted">No operators are currently available for this type.</p>
   <template v-if="operator"><template v-if="type==='data'"><label class="sl-field">Select Plan</label><button v-for="p in operator.plans" :key="priceKey(p.amount,p.product_id)" type="button" class="intl-plan" :class="{active:Number(amount)===Number(p.amount) && productId===(p.product_id??null)}" @click="selectPlan(p)"><span>{{ p.name }}</span><strong>{{ prices[priceKey(p.amount,p.product_id)]!=null?money(prices[priceKey(p.amount,p.product_id)]/100):'Preview price' }}</strong></button><p v-if="!operator.plans.length" class="sl-muted">No data plans are currently available for this operator.</p></template>
   <template v-else><label class="sl-field" for="intl-amount">Amount ({{ operator.currency }})</label><input id="intl-amount" class="sl-input" v-model="amount" type="number" :min="operator.min" :max="operator.max" step="0.01" @input="scheduleAmountPrice"><small class="sl-muted">Min: {{ operator.min }} · Max: {{ operator.max }} {{ operator.currency }}</small></template></template>
   <p class="intl-total" aria-live="polite">You pay: <strong>{{ pricePending?'Calculating…':prices[priceKey()]!=null?money(prices[priceKey()]/100):money(0) }}</strong></p>
   <button type="button" class="sl-btn sl-full" :disabled="!country||!operator||!phone||!amount||pricePending||prices[priceKey()]==null" @click="preview">Continue</button></fieldset>
   <p v-if="message" class="sl-alert mt-3" role="alert">{{ message }}</p>
   <button v-if="countriesFailed" type="button" class="sl-btn ghost" :disabled="busy" @click="loadCountries">Retry Loading Services</button>
   <p v-if="statusMessage" class="mt-3" :class="statusSuccess?'sl-success':'sl-alert'" role="status">{{ statusMessage }}</p>
   <button v-if="operator && phone && amount && prices[priceKey()]==null && !pricePending" type="button" class="sl-btn ghost" :disabled="busy" @click="type==='airtime'?scheduleAmountPrice():loadPrices()">Retry price</button>
   <div v-if="attempt" class="sl-alert mt-3"><p>A payment is awaiting confirmation. Retry with the same quote to check it.</p><button class="sl-btn" :disabled="busy" @click="buy">Check Last Payment</button></div>
  </section>
  <section class="sl-card"><h2>Recent Top-ups</h2><button class="sl-btn ghost" :disabled="busy" @click="loadHistory">Refresh</button><p v-if="!history.length">Your international purchases will appear here.</p><button v-for="h in history" :key="h.reference" class="intl-plan" :disabled="busy" @click="check(h)"><span>{{ h.operator_name }} · {{ h.phone }}<small class="d-block">{{ h.reference }} · {{ h.status }}</small></span><strong>{{ money(h.amount_kobo/100) }}</strong></button></section>
  <div v-if="quote" class="sl-modal-backdrop"><section class="sl-modal" role="dialog" aria-modal="true" aria-labelledby="intl-confirm"><h2 id="intl-confirm">Confirm {{ type==='data'?'Data':'Airtime' }}</h2><p>{{ quote.operator_name }}</p><p>{{ quote.phone }}</p><p class="sl-price">{{ money(quote.amount_kobo/100) }}</p><button class="sl-btn sl-full" :disabled="busy" @click="buy">Pay {{ money(quote.amount_kobo/100) }}</button><button class="sl-btn ghost sl-full mt-2" :disabled="busy" @click="quote=null">Cancel</button><p v-if="message" class="sl-alert" role="alert">{{ message }}</p></section></div>
  <div v-if="receipt" class="sl-modal-backdrop"><section class="sl-modal" role="dialog" aria-modal="true"><h2>{{ receipt.status==='success'?'Top-up Successful':receipt.status==='reversed'?'Top-up Refunded':'Top-up Pending' }}</h2><p>{{ receipt.operator_name }} · {{ receipt.phone }}</p><p class="sl-price">{{ money(receipt.amount_kobo/100) }}</p><p>{{ receipt.reference }}</p><p v-if="receipt.status==='processing' || receipt.status==='pending'">We are confirming delivery. Check this purchase before making another payment.</p><pre v-if="receipt.pin_detail">{{ receipt.pin_detail }}</pre><button class="sl-btn sl-full" @click="receipt=null">Done</button></section></div>
 </main>
</template>
<script>
import axios from 'axios';
import Auth from '../../Auth.js';
import './service-ui.css';
export default {
 data(){return {countries:[],countriesFailed:false,country:'',countrySearch:'',countryPickerOpen:false,type:'airtime',phone:'',operators:[],operator:null,amount:'',productId:null,prices:{},busy:false,message:'',quote:null,attempt:null,receipt:null,history:[],generation:0,priceTimer:null,pricePending:false,statusMessage:'',statusSuccess:false};},
 computed:{filteredCountries(){const q=this.countrySearch.trim().toLowerCase();return this.countries.filter(c=>`${c.name} ${c.code} ${c.calling_code}`.toLowerCase().includes(q));},selectedCountry(){return this.countries.find(c=>c.code===this.country);},key(){return `international_attempt_${Auth.user?.id}`;}},
 async mounted(){try{this.attempt=JSON.parse(localStorage.getItem(this.key)||'null');}catch(e){this.message=this.error(e);}await Promise.all([this.loadCountries(),this.loadHistory()]);},
 beforeUnmount(){clearTimeout(this.priceTimer);this.generation++;},
 methods:{async loadCountries(){this.busy=true;this.countriesFailed=false;this.message='';try{this.countries=(await axios.get('/api/international/countries')).data.data;}catch(e){this.countriesFailed=true;this.message=this.error(e);}finally{this.busy=false;}},openCountryPicker(){this.countryPickerOpen=!this.countryPickerOpen;this.countrySearch='';if(this.countryPickerOpen)this.$nextTick(()=>this.$refs.countrySearchInput?.focus());},selectCountry(c){this.country=c.code;this.countryPickerOpen=false;this.countrySearch='';this.loadOperators();},logoFailed(event,o){const img=event.target;if(o.fallback_logo && !img.src.endsWith(o.fallback_logo)){img.src=o.fallback_logo;}else{img.style.display='none';}},money(n){return Number(n).toLocaleString('en-NG',{style:'currency',currency:'NGN'});},flag(code){return [...code].map(c=>String.fromCodePoint(127397+c.charCodeAt(0))).join('');},error(e){return e.response?.data?.message||'Connection unavailable. Please try again.';},clearPrice(){clearTimeout(this.priceTimer);this.prices={};this.quote=null;this.generation++;this.pricePending=false;this.statusMessage='';},priceKey(amount=this.amount,productId=this.productId){return productId==null?String(amount):`${amount}:${productId}`;},selectPlan(p){this.amount=p.amount;this.productId=p.product_id??null;this.quote=null;this.statusMessage='';this.message='';},input(amount=this.amount,productId=this.productId){return {country_code:this.country,type:this.type,operator_id:this.operator.id,provider:this.operator.provider??'vtugate',product_id:productId,amount,phone:this.phone};},
 phoneChanged(){if(this.type==='airtime')this.scheduleAmountPrice();else this.clearPrice();},
 scheduleAmountPrice(){this.clearPrice();this.message='';const n=Number(this.amount);if(this.type!=='airtime'||!this.operator||!this.country||!this.phone||!Number.isFinite(n)||n<=0||this.attempt)return;
  if((this.operator.min!=null&&n<this.operator.min)||(this.operator.max!=null&&n>this.operator.max)){this.message='Enter an amount within this operator’s limits.';return;}
  this.pricePending=true;const generation=this.generation;const input=this.input();this.priceTimer=setTimeout(async()=>{try{const value=(await axios.post('/api/international/preview',input)).data.data;if(generation===this.generation)this.prices={...this.prices,[input.amount]:value.amount_kobo};}catch(e){if(generation===this.generation)this.message=this.error(e);}finally{if(generation===this.generation)this.pricePending=false;}},500);
 },
 resultMessage(row){this.statusSuccess=['success','reversed'].includes(row.status);this.statusMessage=row.status==='success'?`Top-up successful. You paid ${this.money(row.amount_kobo/100)}.`:row.status==='reversed'?'Your wallet has been refunded.':'We are confirming your top-up. Check Recent Top-ups before paying again.';},
 async loadOperators(){this.clearPrice();this.operator=null;this.amount='';this.productId=null;this.operators=[];if(!this.country)return;this.busy=true;this.message='';try{this.operators=(await axios.get('/api/international/operators',{params:{country_code:this.country,type:this.type}})).data.data;}catch(e){this.message=this.error(e);}finally{this.busy=false;}},
 async choose(o){this.operator=o;this.amount='';this.productId=null;this.clearPrice();await this.loadPrices();},
 async loadPrices(){if(this.type!=='data'||!this.phone||!this.operator||this.busy||this.attempt)return;const generation=++this.generation;this.busy=true;try{for(const p of this.operator.plans){const value=(await axios.post('/api/international/preview',this.input(p.amount,p.product_id??null))).data.data;if(generation!==this.generation)return;this.prices={...this.prices,[this.priceKey(p.amount,p.product_id)]:value.amount_kobo};}}catch(e){this.message=this.error(e);}finally{this.busy=false;}},
 async preview(){this.busy=true;this.message='';try{this.quote=(await axios.post('/api/international/quotes',this.input())).data.data;this.prices={...this.prices,[this.priceKey()]:this.quote.amount_kobo};}catch(e){this.message=this.error(e);}finally{this.busy=false;}},
 async buy(){if(this.busy)return;this.busy=true;this.message='';try{if(!this.attempt){this.attempt={quote_id:this.quote.id};localStorage.setItem(this.key,JSON.stringify(this.attempt));}const result=(await axios.post('/api/international/purchases',this.attempt)).data.data;this.receipt=result;this.resultMessage(result);localStorage.removeItem(this.key);this.attempt=null;this.quote=null;await this.loadHistory();}catch(e){if(axios.isCancel(e)){localStorage.removeItem(this.key);this.attempt=null;}else{this.message=this.error(e);if([401,403,422,428,429].includes(e.response?.status)){localStorage.removeItem(this.key);this.attempt=null;this.quote=null;}}}finally{this.busy=false;}},
 async loadHistory(){try{this.history=(await axios.get('/api/international/purchases')).data.data;}catch(e){this.message=this.error(e);}},async check(h){this.busy=true;try{this.receipt=(await axios.get(`/api/international/purchases/${h.reference}`)).data.data;this.resultMessage(this.receipt);await this.loadHistory();}catch(e){this.message=this.error(e);}finally{this.busy=false;}},
 }
};
</script>
<style scoped>
.intl-screen{max-width:760px}.intl-country-trigger{display:flex;justify-content:space-between;text-align:left}.intl-country-picker{border:1px solid #f0b4bb;border-radius:12px;padding:10px;margin-top:8px}.intl-country-picker ul{list-style:none;padding:0;margin:8px 0 0;max-height:260px;overflow:auto}.intl-country-picker li button{width:100%;border:0;border-radius:8px;background:transparent;color:inherit;padding:12px;text-align:left}.intl-country-picker li button:hover,.intl-country-picker li button[aria-selected="true"]{background:#e3061310}.intl-country-picker small{float:right}.intl-screen .sl-input{border-color:#e30613}.intl-phone{display:flex;align-items:center;border:1px solid #e30613;border-radius:14px;overflow:hidden}.intl-phone strong{padding:0 18px;border-right:1px solid #f4c5ca}.intl-phone input{border:0!important;min-width:0}.intl-plan{display:flex;justify-content:space-between;gap:14px;width:100%;padding:16px;margin:8px 0;border:1px solid #f0b4bb;border-radius:12px;background:transparent;color:inherit;text-align:left}.intl-plan strong{color:#e30613;white-space:nowrap}.intl-plan.active{border:2px solid #e30613;background:#e306130c}.intl-total{text-align:center;padding:14px;background:#e3061310;border-radius:12px;margin:24px 0}.intl-screen fieldset{border:0;padding:0;min-width:0}.intl-screen .sl-platforms{grid-template-columns:repeat(3,minmax(0,1fr))}.intl-screen .sl-platform{min-width:0}.intl-screen .sl-field{margin-top:22px}
</style>
